"""Original starter benchmark covering common quantitative biology tasks."""
from harness import Problem, TestCase


def _problem(id_, title, category, prompt, solution, cases):
    return Problem(id_, title, category, prompt, solution, tuple(TestCase(*case) for case in cases))


